const NL = String.fromCharCode(10);
const S = $('Scope').first().json; const iso = S.iso;
const kb = $('Fetch batch').first().json; if (!Array.isArray(kb.keys)) throw new Error('Fetch batch failed: ' + JSON.stringify(kb).slice(0,200));
const guideRow = $('Get guide').first().json || {}; const rules = guideRow.rules || '';
