const gall = [...(gp1.data||[]), ...((gp1.meta||{}).nextCursor ? (gp2.data||[]) : [])];
const ISO = {640:'en',1056:'es',793:'hr',765:'cs',767:'da',737:'nl',10154:'et',818:'fil',768:'fi',673:'fr',666:'de',761:'el',773:'hu',757:'id',734:'it',733:'ko',10153:'lv',10152:'lt',749:'ms',760:'no',748:'pl',708:'pt',770:'ro',799:'sk',10159:'sl',754:'sv',753:'th',744:'tr',769:'uk',774:'vi'};
